begin;select plan(14);
select has_table('public','quotes','WS10 quotes table exists');select has_table('public','quote_items','WS10 quote items table exists');select has_column('public','quotes','deal_id','quote belongs to deal');select has_column('public','quotes','status','quote lifecycle exists');select has_column('public','quotes','total','quote total exists');select has_column('public','quote_items','discount_percent','line discount exists');select has_column('public','quote_items','tax_percent','line tax exists');select has_index('public','quotes','quotes_org_deal_idx','tenant/deal quote index exists');select has_index('public','quote_items','quote_items_org_quote_idx','tenant/item index exists');select policies_are('public','quotes',array['quotes_tenant_delete','quotes_tenant_insert','quotes_tenant_select','quotes_tenant_update'],'quotes has explicit tenant CRUD policies');select policies_are('public','quote_items',array['quote_items_tenant_delete','quote_items_tenant_insert','quote_items_tenant_select','quote_items_tenant_update'],'quote items has explicit tenant CRUD policies');select isnt_empty($$select 1 from pg_class where oid='public.quotes'::regclass and relrowsecurity$$,'quotes RLS enabled');select isnt_empty($$select 1 from pg_class where oid='public.quote_items'::regclass and relrowsecurity$$,'quote_items RLS enabled');select is_empty($$select 1 from information_schema.role_table_grants where grantee='anon' and table_schema='public' and table_name in('quotes','quote_items')$$,'anon has no quote table grants');select * from finish();rollback;
